     9→import Combine
    10→import SwiftUI
    11→
    12→typealias NotificationSettingsScreenViewModelType = StateStoreViewModelV2<NotificationSettingsScreenViewState, NotificationSettingsScreenViewAction>
    13→
    14→class NotificationSettingsScreenViewModel: NotificationSettingsScreenViewModelType, NotificationSettingsScreenViewModelProtocol {
    15→    private var actionsSubject: PassthroughSubject<NotificationSettingsScreenViewModelAction, Never> = .init()
    16→    private let appSettings: AppSettings
    17→    private let userNotificationCenter: UserNotificationCenterProtocol
    18→    private let notificationSettingsProxy: NotificationSettingsProxyProtocol
    19→    // periphery:ignore - cancellable tasks get cancelled when reassigned
    20→    @CancellableTask private var fetchSettingsTask: Task<Void, Error>?
    21→    
    22→    var actions: AnyPublisher<NotificationSettingsScreenViewModelAction, Never> {
    23→        actionsSubject.eraseToAnyPublisher()
    24→    }
    25→
    26→    init(appSettings: AppSettings, userNotificationCenter: UserNotificationCenterProtocol, notificationSettingsProxy: NotificationSettingsProxyProtocol, isModallyPresented: Bool) {
    27→        self.appSettings = appSettings
    28→        self.userNotificationCenter = userNotificationCenter
    29→        self.notificationSettingsProxy = notificationSettingsProxy
    30→        
    31→        let bindings = NotificationSettingsScreenViewStateBindings(enableNotifications: appSettings.enableNotifications)
    32→        super.init(initialViewState: NotificationSettingsScreenViewState(bindings: bindings, isModallyPresented: isModallyPresented))
    33→                
    34→        // Listen for changes to AppSettings.
    35→        appSettings.$enableNotifications
    36→            .weakAssign(to: \.state.bindings.enableNotifications, on: self)
    37→            .store(in: &cancellables)
    38→        
    39→        setupDidBecomeActiveSubscription()
    40→        setupNotificationSettingsSubscription()
    41→    }
    42→    
    43→    func fetchInitialContent() {
    44→        fetchSettings()
    45→    }
    46→        
    47→    // MARK: - Public
    48→    
    49→    override func process(viewAction: NotificationSettingsScreenViewAction) {
    50→        switch viewAction {
    51→        case .changedEnableNotifications:
    52→            toggleNotifications()
    53→        case .groupChatsTapped:
    54→            actionsSubject.send(.editDefaultMode(chatType: .groupChat))
    55→        case .directChatsTapped:
    56→            actionsSubject.send(.editDefaultMode(chatType: .oneToOneChat))
    57→        case .roomMentionChanged:
    58→            guard let settings = state.settings, settings.roomMentionsEnabled != state.bindings.roomMentionsEnabled else {
    59→                return
    60→            }
    61→            Task { await enableRoomMention(state.bindings.roomMentionsEnabled) }
    62→        case .callsChanged:
    63→            guard let settings = state.settings, settings.callsEnabled != state.bindings.callsEnabled else {
    64→                return
    65→            }
    66→            Task { await enableCalls(state.bindings.callsEnabled) }
    67→        case .invitationsChanged:
    68→            guard let settings = state.settings, settings.invitationsEnabled != state.bindings.invitationsEnabled else {
    69→                return
    70→            }
    71→            Task { await enableInvitations(state.bindings.invitationsEnabled) }
    72→        case .close:
    73→            actionsSubject.send(.close)
    74→        case .fixConfigurationMismatchTapped:
    75→            Task { await fixConfigurationMismatch() }
    76→        }
    77→    }
    78→    
    79→    // MARK: - Private
    80→        
    81→    func readSystemAuthorizationStatus() async {
    82→        state.isUserPermissionGranted = await userNotificationCenter.authorizationStatus() == .authorized
    83→    }
    84→
    85→    func toggleNotifications() {
    86→        appSettings.enableNotifications.toggle()
    87→    }
    88→    
    89→    private func setupDidBecomeActiveSubscription() {
    90→        // Refresh authorization status uppon UIApplication.didBecomeActiveNotification notification
    91→        NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)
    92→            .sink { [weak self] _ in
    93→                Task {
    94→                    await self?.readSystemAuthorizationStatus()
    95→                }
    96→            }
    97→            .store(in: &cancellables)
    98→        
    99→        Task {
   100→            await readSystemAuthorizationStatus()
   101→        }
   102→    }
   103→    
   104→    private func setupNotificationSettingsSubscription() {
   105→        notificationSettingsProxy.callbacks
   106→            .receive(on: DispatchQueue.main)
   107→            .sink { [weak self] callback in
   108→                guard let self else { return }
   109→                
   110→                switch callback {
   111→                case .settingsDidChange:
   112→                    self.fetchSettings()
   113→                }
   114→            }
   115→            .store(in: &cancellables)
   116→    }
   117→    
   118→    private func fetchSettings() {
   119→        fetchSettingsTask = Task {
   120→            var inconsistentSettings: [NotificationSettingsScreenInvalidSetting] = []
   121→            // Group chats
   122→            var groupChatsMode = await notificationSettingsProxy.getDefaultRoomNotificationMode(isEncrypted: false, isOneToOne: false)
   123→            let encryptedGroupChatsMode = await notificationSettingsProxy.getDefaultRoomNotificationMode(isEncrypted: true, isOneToOne: false)
   124→
   125→            // Direct chats
   126→            var directChatsMode = await notificationSettingsProxy.getDefaultRoomNotificationMode(isEncrypted: false, isOneToOne: true)
   127→            let encryptedDirectChatsMode = await notificationSettingsProxy.getDefaultRoomNotificationMode(isEncrypted: true, isOneToOne: true)
   128→                        
   129→            // Old clients were having specific settings for encrypted and unencrypted rooms,
   130→            // so it's possible for `group chats` and `direct chats` settings to be inconsistent (e.g. encrypted `direct chats` can have a different mode that unencrypted `direct chats`)
   131→            if groupChatsMode != encryptedGroupChatsMode {
   132→                groupChatsMode = .allMessages
   133→                // a default setting for a chat can only be `.allMessages` or `.mentionsAndKeywordsOnly`.
   134→                inconsistentSettings.append(.init(chatType: .groupChat, isEncrypted: encryptedGroupChatsMode != .allMessages))
   135→            }
   136→            if directChatsMode != encryptedDirectChatsMode {
   137→                directChatsMode = .allMessages
   138→                // a default setting for a chat can only be `.allMessages` or `.mentionsAndKeywordsOnly`.
   139→                inconsistentSettings.append(.init(chatType: .oneToOneChat, isEncrypted: encryptedDirectChatsMode != .allMessages))
   140→            }
   141→            
   142→            // The following calls may fail if the associated push rule doesn't exist
   143→            let roomMentionsEnabled = try? await notificationSettingsProxy.isRoomMentionEnabled()
   144→            let callEnabled = try? await notificationSettingsProxy.isCallEnabled()
   145→            let invitationsEnabled = try? await notificationSettingsProxy.isInviteForMeEnabled()
   146→                        
   147→            guard !Task.isCancelled else { return }
   148→
   149→            let notificationSettings = NotificationSettingsScreenSettings(groupChatsMode: groupChatsMode,
   150→                                                                          directChatsMode: directChatsMode,
   151→                                                                          roomMentionsEnabled: roomMentionsEnabled,
   152→                                                                          callsEnabled: callEnabled,
   153→                                                                          invitationsEnabled: invitationsEnabled,
   154→                                                                          inconsistentSettings: inconsistentSettings)
   155→
   156→            state.settings = notificationSettings
   157→            state.bindings.roomMentionsEnabled = notificationSettings.roomMentionsEnabled ?? false
   158→            state.bindings.callsEnabled = notificationSettings.callsEnabled ?? false
   159→            state.bindings.invitationsEnabled = notificationSettings.invitationsEnabled ?? false
   160→        }
   161→    }
   162→    
   163→    private func fixConfigurationMismatch() async {
   164→        guard let settings = state.settings, !settings.inconsistentSettings.isEmpty, !state.fixingConfigurationMismatch else { return }
   165→        state.fixingConfigurationMismatch = true
   166→        
   167→        var failures: [NotificationSettingsScreenInvalidSetting] = []
   168→        for inconsistentSetting in settings.inconsistentSettings {
   169→            do {
   170→                try await notificationSettingsProxy.setDefaultRoomNotificationMode(isEncrypted: inconsistentSetting.isEncrypted, isOneToOne: inconsistentSetting.chatType == .oneToOneChat, mode: .allMessages)
   171→            } catch {
   172→                failures.append(inconsistentSetting)
   173→            }
   174→        }
   175→        
   176→        if !failures.isEmpty {
   177→            state.bindings.alertInfo = AlertInfo(id: .fixMismatchConfigurationFailed,
   178→                                                 title: L10n.commonError,
   179→                                                 message: L10n.screenNotificationSettingsFailedFixingConfiguration,
   180→                                                 primaryButton: .init(title: L10n.actionOk, action: nil))
   181→        }
   182→        state.fixingConfigurationMismatch = false
   183→    }
   184→    
   185→    private func enableRoomMention(_ enable: Bool) async {
   186→        guard let notificationSettings = state.settings else { return }
   187→        do {
   188→            state.applyingChange = true
   189→            MXLog.info("setRoomMentionEnabled(\(enable))")
   190→            try await notificationSettingsProxy.setRoomMentionEnabled(enabled: enable)
   191→        } catch {
   192→            state.bindings.alertInfo = AlertInfo(id: .alert)
   193→            state.bindings.roomMentionsEnabled = notificationSettings.roomMentionsEnabled ?? false
   194→        }
   195→        state.applyingChange = false
   196→    }
   197→        
   198→    func enableCalls(_ enable: Bool) async {
   199→        guard let notificationSettings = state.settings else { return }
   200→        do {
   201→            state.applyingChange = true
   202→            MXLog.info("setCallEnabled(\(enable))")
   203→            try await notificationSettingsProxy.setCallEnabled(enabled: enable)
   204→        } catch {
   205→            state.bindings.alertInfo = AlertInfo(id: .alert)
   206→            state.bindings.callsEnabled = notificationSettings.callsEnabled ?? false
   207→        }
   208→        state.applyingChange = false
   209→    }
   210→    
   211→    func enableInvitations(_ enable: Bool) async {
   212→        guard let notificationSettings = state.settings else { return }
   213→        do {
   214→            state.applyingChange = true
   215→            MXLog.info("setInviteForMeEnabled(\(enable))")
   216→            try await notificationSettingsProxy.setInviteForMeEnabled(enabled: enable)
   217→        } catch {
   218→            state.bindings.alertInfo = AlertInfo(id: .alert)
   219→            state.bindings.callsEnabled = notificationSettings.invitationsEnabled ?? false
   220→        }
   221→        state.applyingChange = false
   222→    }
   223→}
   224→
   225→extension UNUserNotificationCenter {
   226→    func authorizationStatus() async -> UNAuthorizationStatus {
   227→        await notificationSettings().authorizationStatus
   228→    }
   229→}
