    21→                    userPermissionSection
    22→                }
    23→                
    24→                enableNotificationSection
    25→                
    26→                if context.enableNotifications {
    27→                    roomsNotificationSection
    28→                    
    29→                    if context.viewState.settings?.roomMentionsEnabled != nil {
    30→                        mentionsSection
    31→                    }
    32→                    
    33→                    if context.viewState.showCallsSettings, context.viewState.settings?.callsEnabled != nil {
    34→                        callsSection
    35→                    }
    36→                    
    37→                    if context.viewState.settings?.invitationsEnabled != nil {
    38→                        additionalSettingsSection
    39→                    }
    40→                }
    41→            }
    42→        }
    43→        .compoundList()
    44→        .navigationTitle(L10n.screenNotificationSettingsTitle)
