    93→                }
    94→        }
    95→    }
    96→    
    97→    private var roomsNotificationSection: some View {
    98→        Section {
    99→            // Group chats
   100→            ListRow(label: .plain(title: L10n.screenNotificationSettingsGroupChats),
   101→                    details: context.viewState.settings.map {
   102→                        .title(context.viewState.strings.string(for: $0.groupChatsMode))
   103→                    } ?? .isWaiting(true),
   104→                    kind: .navigationLink {
   105→                        context.send(viewAction: .groupChatsTapped)
   106→                    })
   107→                    .disabled(context.viewState.settings == nil)
   108→                    .accessibilityIdentifier(A11yIdentifiers.roomDetailsScreen.notifications)
   109→            
   110→            // Direct chats
   111→            ListRow(label: .plain(title: L10n.screenNotificationSettingsDirectChats),
   112→                    details: context.viewState.settings.map {
   113→                        .title(context.viewState.strings.string(for: $0.directChatsMode))
   114→                    } ?? .isWaiting(true),
   115→                    kind: .navigationLink {
   116→                        context.send(viewAction: .directChatsTapped)
   117→                    })
   118→                    .disabled(context.viewState.settings == nil)
   119→                    .accessibilityIdentifier(A11yIdentifiers.roomDetailsScreen.notifications)
   120→            
   121→        } header: {
   122→            Text(L10n.screenNotificationSettingsNotificationSectionTitle)
   123→                .compoundListSectionHeader()
   124→        }
   125→    }
   126→        
   127→    private var mentionsSection: some View {
   128→        Section {
   129→            ListRow(label: .plain(title: L10n.screenNotificationSettingsRoomMentionLabel),
   130→                    kind: .toggle($context.roomMentionsEnabled))
   131→                .disabled(context.viewState.settings?.roomMentionsEnabled == nil)
   132→                .allowsHitTesting(!context.viewState.applyingChange)
   133→                .onChange(of: context.roomMentionsEnabled) {
   134→                    context.send(viewAction: .roomMentionChanged)
   135→                }
   136→        } header: {
   137→            Text(L10n.screenNotificationSettingsMentionsSectionTitle)
   138→                .compoundListSectionHeader()
   139→        }
   140→    }
   141→    
   142→    private var callsSection: some View {
   143→        Section {
   144→            ListRow(label: .plain(title: L10n.screenNotificationSettingsCallsLabel),
   145→                    kind: .toggle($context.callsEnabled))
   146→                .disabled(context.viewState.settings?.callsEnabled == nil)
   147→                .allowsHitTesting(!context.viewState.applyingChange)
   148→                .onChange(of: context.callsEnabled) {
   149→                    context.send(viewAction: .callsChanged)
   150→                }
   151→        } header: {
   152→            Text(L10n.screenNotificationSettingsAdditionalSettingsSectionTitle)
   153→                .compoundListSectionHeader()
   154→        }
   155→    }
   156→    
   157→    private var additionalSettingsSection: some View {
   158→        Section {
   159→            ListRow(label: .plain(title: L10n.screenNotificationSettingsInviteForMeLabel),
   160→                    kind: .toggle($context.invitationsEnabled))
   161→                .disabled(context.viewState.settings?.invitationsEnabled == nil)
   162→                .allowsHitTesting(!context.viewState.applyingChange)
   163→                .onChange(of: context.invitationsEnabled) {
   164→                    context.send(viewAction: .invitationsChanged)
   165→                }
   166→        } header: {
   167→            Text(L10n.screenNotificationSettingsAdditionalSettingsSectionTitle)
   168→                .compoundListSectionHeader()
   169→        }
   170→    }
   171→    
   172→    private var configurationMismatchSection: some View {
   173→        Section {
   174→            ListRow(kind: .custom {
   175→                VStack(alignment: .leading, spacing: 16) {
   176→                    VStack(alignment: .leading, spacing: 8) {
   177→                        Text(L10n.screenNotificationSettingsConfigurationMismatch)
   178→                            .font(.compound.bodyLGSemibold)
   179→                        Text(L10n.screenNotificationSettingsConfigurationMismatchDescription)
   180→                            .font(.compound.bodyMD)
   181→                            .foregroundColor(.compound.textSecondary)
   182→                    }
   183→                    Button {
   184→                        context.send(viewAction: .fixConfigurationMismatchTapped)
   185→                    } label: {
   186→                        Text(L10n.actionContinue)
   187→                            .frame(maxWidth: .infinity)
   188→                    }
   189→                    .buttonStyle(.compound(.primary, size: .medium))
   190→                    .disabled(context.viewState.fixingConfigurationMismatch)
   191→                    .accessibilityIdentifier(A11yIdentifiers.notificationSettingsScreen.fixMismatchConfiguration)
   192→                }
   193→                .padding(.horizontal, ListRowPadding.horizontal)
   194→                .padding(.vertical, 24)
   195→            })
   196→        }
   197→    }
   198→}
