     9→import Foundation
    10→
    11→enum NotificationSettingsEditScreenViewModelAction {
    12→    case requestRoomNotificationSettingsPresentation(roomID: String)
    13→}
    14→
    15→enum NotificationSettingsEditScreenDefaultMode {
    16→    case allMessages
    17→    case mentionsAndKeywordsOnly
    18→}
    19→
    20→struct NotificationSettingsEditScreenViewState: BindableState {
    21→    var bindings: NotificationSettingsEditScreenViewStateBindings
    22→    var strings: NotificationSettingsEditScreenStrings
    23→    var availableDefaultModes: [NotificationSettingsEditScreenDefaultMode] = [.allMessages, .mentionsAndKeywordsOnly]
    24→    var defaultMode: NotificationSettingsEditScreenDefaultMode?
    25→    var pendingMode: NotificationSettingsEditScreenDefaultMode?
    26→    var roomsWithUserDefinedMode: [NotificationSettingsEditScreenRoom] = []
    27→    var canPushEncryptedEvents = false
    28→
    29→    func isSelected(mode: NotificationSettingsEditScreenDefaultMode) -> Bool {
    30→        pendingMode == nil && defaultMode == mode
    31→    }
    32→    
    33→    func description(for mode: NotificationSettingsEditScreenDefaultMode) -> String? {
    34→        guard mode == .mentionsAndKeywordsOnly,
    35→              !canPushEncryptedEvents else {
    36→            return nil
    37→        }
    38→        return L10n.screenNotificationSettingsMentionsOnlyDisclaimer
    39→    }
    40→    
    41→    var displayRoomsWithCustomSettings: Bool {
    42→        !roomsWithUserDefinedMode.isEmpty
    43→    }
    44→}
    45→
    46→struct NotificationSettingsEditScreenViewStateBindings {
    47→    var alertInfo: AlertInfo<NotificationSettingsEditScreenErrorType>?
    48→}
    49→
    50→enum NotificationSettingsEditScreenViewAction {
    51→    case setMode(NotificationSettingsEditScreenDefaultMode)
    52→    case selectRoom(roomIdentifier: String)
    53→}
    54→
    55→enum NotificationSettingsEditScreenErrorType: Hashable {
    56→    case setModeFailed
    57→}
    58→
    59→struct NotificationSettingsEditScreenStrings {
    60→    let navigationTitle: String
    61→    let modeSectionTitle: String
    62→    
    63→    init(chatType: NotificationSettingsChatType) {
    64→        switch chatType {
    65→        case .oneToOneChat:
    66→            navigationTitle = L10n.screenNotificationSettingsDirectChats
    67→            modeSectionTitle = L10n.screenNotificationSettingsEditScreenDirectSectionHeader
    68→        case .groupChat:
    69→            navigationTitle = L10n.screenNotificationSettingsGroupChats
    70→            modeSectionTitle = L10n.screenNotificationSettingsEditScreenGroupSectionHeader
    71→        }
    72→    }
    73→    
    74→    func string(for mode: NotificationSettingsEditScreenDefaultMode) -> String {
    75→        switch mode {
    76→        case .allMessages:
