    63→    private func setupNotificationSettingsSubscription() {
    64→        notificationSettingsProxy.callbacks
    65→            .receive(on: DispatchQueue.main)
    66→            .sink { [weak self] callback in
    67→                guard let self else { return }
    68→                
    69→                switch callback {
