    87→            let canPushEncryptedEvents = await notificationSettingsProxy.canPushEncryptedEventsToDevice()
    88→            guard !Task.isCancelled else { return }
    89→            
    90→            switch mode {
    91→            case .allMessages:
    92→                state.defaultMode = .allMessages
    93→            case .mentionsAndKeywordsOnly:
    94→                state.defaultMode = .mentionsAndKeywordsOnly
    95→            default:
    96→                state.defaultMode = nil
