   161→    private func setMode(_ mode: NotificationSettingsEditScreenDefaultMode) {
   162→        guard state.pendingMode == nil, !state.isSelected(mode: mode) else { return }
   163→        let roomNotificationModeProxy: RoomNotificationModeProxy
   164→        switch mode {
   165→        case .allMessages:
   166→            roomNotificationModeProxy = .allMessages
   167→        case .mentionsAndKeywordsOnly:
   168→            roomNotificationModeProxy = .mentionsAndKeywordsOnly
   169→        }
   170→        state.pendingMode = mode
   171→        Task {
   172→            do {
   173→                // On modern clients, we don't have different settings for encrypted and non-encrypted rooms.
   174→                let isOneToOne = chatType == .oneToOneChat
   175→                try await notificationSettingsProxy.setDefaultRoomNotificationMode(isEncrypted: true, isOneToOne: isOneToOne, mode: roomNotificationModeProxy)
   176→                try await notificationSettingsProxy.setDefaultRoomNotificationMode(isEncrypted: false, isOneToOne: isOneToOne, mode: roomNotificationModeProxy)
   177→            } catch {
   178→                // In case of failure, we let the user retry
   179→                let retryAction: () -> Void = { [weak self] in
   180→                    self?.setMode(mode)
   181→                }
   182→                state.bindings.alertInfo = AlertInfo(id: .setModeFailed,
   183→                                                     title: L10n.commonError,
   184→                                                     message: L10n.screenNotificationSettingsEditFailedUpdatingDefaultMode,
   185→                                                     primaryButton: .init(title: L10n.actionCancel, role: .cancel, action: nil),
   186→                                                     secondaryButton: .init(title: L10n.actionRetry, action: retryAction))
   187→            }
   188→            state.pendingMode = nil
   189→        }
   190→    }
   191→}
